contracts/mainSystem/controller/TaskCont.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../../system/utils/addressUtils.sol";
import "../../system/utils/ReentrancyGuard.sol";
import "../../Pipe/AccesControlPipes.sol";
import "../../system/interfaces/taskCTCcall/ITaskController.sol";
import "../../system/interfaces/taskCTCcall/ITaskData.sol";
import "../../system/interfaces/taskCTCcall/ITaskLifecycleLogic.sol";
import "../../system/interfaces/taskCTCcall/IJoinRequestLogic.sol";
import "../../system/interfaces/taskCTCcall/ISubmissionLogic.sol";
import "../../system/interfaces/taskCTCcall/ICancellationLogic.sol";
import "../../system/interfaces/IAddressRegistry.sol";
import "../../system/interfaces/CTCcall/IUsers.sol";
import "../../system/interfaces/IDataContract.sol";

import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title TaskController
 * @notice Main entry point for task system - routes to logic contracts
 * @dev Handles access control, pausable, reentrancy protection, and call aggregation
 */
contract TaskController is
    ITaskController,
    AddressUtils,
    Initializable,
    UUPSUpgradeable,
    PausableUpgradeable,
    MainAccesControlPipes,
    SystemReentrancyGuard
{
    // =============================================================
    // STATE VARIABLES
    // =============================================================

    IAddressRegistry public addressRegistry;

    uint256[40] private ___gap;

    // =============================================================
    // EVENTS
    // =============================================================
    event ControllerEvent(string eventName, uint256 indexed taskId, address indexed user);

    // =============================================================
    // ERRORS
    // =============================================================
    error systemError(string errName);
    error MainContractErr(string errName);

    // =============================================================
    // Helper functions to get logic contract instances
    // =============================================================

    function _getTaskDataContract() internal view returns (ITaskData) {
        return ITaskData(addressRegistry.__taskComponentsAddr().dataContract);
    }

    function _getTaskLifecycleLogicContract() internal view returns (ITaskLifecycleLogic) {
        return ITaskLifecycleLogic(addressRegistry.__taskComponentsAddr().taskLifecycleModule);
    }

    function _getTaskJoinRequestContract() internal view returns (IJoinRequestLogic) {
        return IJoinRequestLogic(addressRegistry.__taskComponentsAddr().joinModule);
    }

    function _getTaskSubmissionContract() internal view returns (ISubmissionLogic) {
        return ISubmissionLogic(addressRegistry.__taskComponentsAddr().submisionModule);
    }

    function _getTaskCancellationContract() internal view returns (ICancellationLogic) {
        return ICancellationLogic(addressRegistry.__taskComponentsAddr().cancelModule);
    }


    // =============================================================
    // MODIFIERS
    // =============================================================

    modifier taskExists(uint256 _taskId) {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(_taskId);
        if (!t.exists) revert systemError("TaskDoesNotExist");
        _;
    }

    modifier onlyTaskCreator(uint256 _taskId) {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(_taskId);
        if (t.creator != msg.sender) revert systemError("NotTaskCreator");
        _;
    }

    modifier onlyTaskMember(uint256 _taskId) {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(_taskId);
        if (t.member != msg.sender) revert systemError("NotTaskMember");
        _;
    }

    modifier onlyRegistered() {
        if (!IUsers(addressRegistry.__usersContract()).__isRegistered(msg.sender)) {
            revert systemError("NotRegistered");
        }
        _;
    }

    modifier onlyOwner {
        __onlyOwner(addressRegistry.__accessControlContract());
        _;
    }

    modifier onlyUser() {
        __onlyUser(addressRegistry.__accessControlContract());  
        _;
    }


    // =============================================================
    // INITIALIZATION
    // =============================================================

    /**
     * @notice Initializes the TaskController with all logic contract addresses
     */
    function initialize(
        address _registryAddress
    ) public initializer {
        if (_registryAddress == address(0)) revert systemError("ZeroAddress");

        __ReentrancyGuard_init();
        __Pausable_init();

        addressRegistry = IAddressRegistry(_registryAddress);
    }

    // =============================================================
    // TASK LIFECYCLE FUNCTIONS
    // =============================================================

    /**
     * @notice Creates a new task
     * @dev SECURITY FIX C-1: Accept ETH to deposit to UsersContract vault first, not to logic module
     */
    function createTask(
        string memory _Title,
        string memory _GithubURL,
        uint128 _DeadlineHours,
        uint128 _MaximumRevision,
        uint256 _rewardAmount,
        address _user
    ) external payable override whenNotPaused onlyRegistered nonReentrant onlyUser {
        // SECURITY FIX C-2: Ensure caller is the user they claim to be
        if (msg.sender != _user) revert systemError("CallerMustBeUser");
        
        // SECURITY FIX C-1: Deposit ETH to UsersContract vault instead of logic module
        IUsers usersContract = IUsers(addressRegistry.__usersContract());
        if (msg.value > 0) {
            (bool success, ) = addressRegistry.__usersContract().call{value: msg.value}("");
            if (!success) revert systemError("DepositFailed");
            usersContract.__addUserBalance(_user, msg.value);
        }
        
        _getTaskLifecycleLogicContract().__createTask(
            _Title,
            _GithubURL,
            _DeadlineHours,
            _MaximumRevision,
            _rewardAmount,
            _user
        );
        emit ControllerEvent("TaskCreated", 0, _user);
    }

    /**
     * @notice Deletes a task
     */
    function deleteTask(uint256 _taskId, address _user)
        external
        override
        nonReentrant
        onlyTaskCreator(_taskId)
        onlyRegistered
    {
        // SECURITY FIX C-2, M-2: Ensure caller is the user they claim to be
        if (msg.sender != _user) revert systemError("CallerMustBeUser");
        
        _getTaskLifecycleLogicContract().__deleteTask(_taskId, _user);
        emit ControllerEvent("TaskDeleted", _taskId, _user);
    }

    /**
     * @notice Activates a task by providing creator stake
     * @dev SECURITY FIX C-1: Deposit ETH to UsersContract vault first, not to logic module
     */
    function activateTask(uint256 taskId, address user)
        external
        payable
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        nonReentrant
        whenNotPaused
    {
        // SECURITY FIX C-2, H-7: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        // SECURITY FIX C-1: Deposit ETH to UsersContract vault instead of logic module
        IUsers usersContract = IUsers(addressRegistry.__usersContract());
        if (msg.value > 0) {
            (bool success, ) = addressRegistry.__usersContract().call{value: msg.value}("");
            if (!success) revert systemError("DepositFailed");
            usersContract.__addUserBalance(user, msg.value);
        }
        
        _getTaskLifecycleLogicContract().__activateTask(taskId, user);
        emit ControllerEvent("TaskActive", taskId, user);
    }

    /**
     * @notice Opens registration for task
     */
    function openRegistration(uint256 taskId)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        whenNotPaused
    {
        _getTaskLifecycleLogicContract().__openRegistration(taskId);
        emit ControllerEvent("RegistrationOpened", taskId, msg.sender);
    }

    /**
     * @notice Closes registration for task
     */
    function closeRegistration(uint256 taskId)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        whenNotPaused
    {
        _getTaskLifecycleLogicContract().__closeRegistration(taskId);
        emit ControllerEvent("RegistrationClosed", taskId, msg.sender);
    }

    // =============================================================
    // JOIN REQUEST FUNCTIONS
    // =============================================================

    /**
     * @notice Requests to join a task
     * @dev SECURITY FIX C-1: Deposit ETH to UsersContract vault first, not to logic module
     */
    function requestJoinTask(uint256 taskId, address user)
        external
        payable
        override
        taskExists(taskId)
        whenNotPaused
        onlyRegistered
        onlyUser
    {
        // SECURITY FIX C-2, C-5: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        // SECURITY FIX C-1: Deposit ETH to UsersContract vault instead of logic module
        IUsers usersContract = IUsers(addressRegistry.__usersContract());
        if (msg.value > 0) {
            (bool success, ) = addressRegistry.__usersContract().call{value: msg.value}("");
            if (!success) revert systemError("DepositFailed");
            usersContract.__addUserBalance(user, msg.value);
        }
        
        _getTaskJoinRequestContract().__requestJoinTask(taskId, user);
        emit ControllerEvent("JoinRequested", taskId, user);
    }

    /**
     * @notice Withdraws a pending join request
     */
    function withdrawJoinRequest(uint256 taskId, address user)
        external
        override
        nonReentrant
        onlyRegistered
        onlyUser
    {
        // SECURITY FIX C-2: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        _getTaskJoinRequestContract().__withdrawJoinRequest(taskId, user);
        emit ControllerEvent("JoinrequestCancelled", taskId, user);
    }

    /**
     * @notice Approves a join request
     */
    function approveJoinRequest(uint256 taskId, address applicant)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        nonReentrant
        whenNotPaused
    {
        _getTaskJoinRequestContract().__approveJoinRequest(taskId, applicant);
        emit ControllerEvent("JoinApproved", taskId, applicant);
    }

    function approveJoinRequestAndRejectOthers(uint256 taskId, address applicant)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        nonReentrant
        whenNotPaused
    {
        _getTaskJoinRequestContract().__approveAndRejectOthers(taskId, applicant);
        emit ControllerEvent("JoinApproved", taskId, applicant);
    }

    /**
     * @notice Rejects a join request
     */
    function rejectJoinRequest(uint256 taskId, address _applicant)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        nonReentrant
        whenNotPaused
    {
        _getTaskJoinRequestContract().__rejectJoinRequest(taskId, _applicant);
        emit ControllerEvent("JoinRejected", taskId, _applicant);
    }

    // =============================================================
    // SUBMISSION FUNCTIONS
    // =============================================================

    /**
     * @notice Submits a task for review
     */
    function requestSubmitTask(
        uint256 taskId,
        string calldata PullRequestURL,
        string calldata Note,
        address user
    )
        external
        override
        taskExists(taskId)
        onlyTaskMember(taskId)
        whenNotPaused
        onlyUser
    {
        // SECURITY FIX C-2: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        _getTaskSubmissionContract().__requestSubmitTask(taskId, PullRequestURL, Note, user);
        emit ControllerEvent("TaskSubmitted", taskId, user);
    }

    /**
     * @notice Resubmits a task after revision
     */
    function reSubmitTask(
        uint256 taskId,
        string calldata Note,
        string calldata GithubFixedURL,
        address user
    )
        external
        override
        taskExists(taskId)
        onlyTaskMember(taskId)
        whenNotPaused
        onlyUser {
        // SECURITY FIX C-2: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        _getTaskSubmissionContract().__reSubmitTask(taskId, Note, GithubFixedURL, user);
        emit ControllerEvent("TaskReSubmitted", taskId, user);
    }

    /**
     * @notice Requests revision on a submission
     */
    function requestRevision(
        uint256 taskId,
        string calldata Note,
        uint256 additionalDeadlineHours
    ) external override onlyTaskCreator(taskId) whenNotPaused {
        _getTaskSubmissionContract().__requestRevision(taskId, Note, additionalDeadlineHours);
        emit ControllerEvent("RevisionRequested", taskId, msg.sender);
    }

    /**
     * @notice Approves a task submission
     */
    function approveTask(uint256 taskId)
        external
        override
        taskExists(taskId)
        onlyTaskCreator(taskId)
        nonReentrant
        whenNotPaused
    {
        _getTaskSubmissionContract().__approveTask(taskId);
        emit ControllerEvent("TaskApproved", taskId, msg.sender);
    }

    // =============================================================
    // CANCELLATION FUNCTIONS
    // =============================================================

    /**
     * @notice Cancels a task by creator or member
     */
    function cancelByMe(uint256 taskId, address user)
        external
        override
        taskExists(taskId)
        nonReentrant
        onlyUser
        whenNotPaused
    {
        // SECURITY FIX C-2: Ensure caller is the user they claim to be
        if (msg.sender != user) revert systemError("CallerMustBeUser");
        
        _getTaskCancellationContract().__cancelByMe(taskId, user);
        emit ControllerEvent("TaskCancelledByMe", taskId, user);
    }

    /**
     * @notice Triggers deadline consequence
     * @dev SECURITY FIX M-3: Only task creator can trigger deadline
     */
    function triggerDeadline(uint256 taskId)
        external
        override
        taskExists(taskId)
        whenNotPaused
        nonReentrant
        onlyTaskCreator(taskId)
    {
        _getTaskCancellationContract().__triggerDeadline(taskId);
        emit ControllerEvent("DeadlineTriggered", taskId, msg.sender);
    }

    // =============================================================
    // VIEW FUNCTIONS
    // =============================================================

    /**
     * @notice Gets join request count for task
     */
    function getJoinRequestCount(uint256 taskId)
        external
        view
        override
        returns (uint256)
    {
        return _getTaskDataContract().__getJoinRequestCount(taskId);
    }

    /**
     * @notice Gets required member stake for task
     */
    function getMemberRequiredStake(uint256 taskId)
        public
        view
        override
        taskExists(taskId)
        returns (uint256)
    {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        return (t.reward *
            IDataContract(addressRegistry.__dataContract()).__getMemberStakeFromRewardPercentage()) / 100;
    }

    /**
     * @notice Calculates required creator stake
     */
    function ___getCreatorStake(
        uint128 DeadlineHours,
        uint128 MaximumRevision,
        uint256 rewardWei,
        address Caller
    ) public view override returns (uint256) {
        return _getTaskLifecycleLogicContract().___getCreatorStake(
            DeadlineHours,
            MaximumRevision,
            rewardWei,
            Caller
        );
    }

    /**
     * @notice Calculates project value
     */
    function ___getProjectValue(
        uint128 DeadlineHours,
        uint128 MaximumRevision,
        uint256 rewardWei,
        address Caller
    ) public view override returns (uint256) {
        return _getTaskLifecycleLogicContract().___getProjectValue(
            DeadlineHours,
            MaximumRevision,
            rewardWei,
            Caller
        );
    }

    // =============================================================
    // OWNER FUNCTIONS
    // =============================================================

    /**
     * @notice Withdraws accumulated protocol fees
     * @dev SECURITY FIX NEW-H-1: Fees are stored in UsersContract, withdraw from there
     */
    function withdrawToSystemWallet()
        external
        onlyOwner
        nonReentrant
        whenNotPaused
    {
        // SECURITY FIX C-4: Fix tuple destructuring order
        // __getGlobalState returns (taskCounter, feeCollected) in that order
        (, uint256 feeCollected) = _getTaskDataContract().__getGlobalState();
        if (feeCollected > 0) {
            _getTaskDataContract().__decreaseFee(feeCollected);
            (bool ok, ) = addressRegistry.__walletContract().call{value: feeCollected}("");
            if (!ok) revert systemError("WithdrawFailed");
        }
    }

    /**
     * @notice Change address registry
     */
    function __changeControllerAndModuleAddressRegistry(address newAddress) external override whenNotPaused onlyOwner{
        if (newAddress == address(0)) {
            revert systemError("ZeroAddress");
        }

        _getTaskLifecycleLogicContract().__changeAddressRegistry(newAddress);
        _getTaskJoinRequestContract().__changeAddressRegistry(newAddress);
        _getTaskSubmissionContract().__changeAddressRegistry(newAddress);
        _getTaskCancellationContract().__changeAddressRegistry(newAddress);

        addressRegistry = IAddressRegistry(newAddress);
        emit ControllerEvent("addressRegistryUpdated", 0, newAddress);
    }

    /**
     * @notice Pauses the contract
     */
    function pause(address caller)
        external
        onlyOwner
    {
        if (caller == address(0)) revert systemError("ZeroAddress");
        _pause();
    }

    /**
     * @notice Unpauses the contract
     */
    function unpause(address caller)
        external
        onlyOwner
    {
        if (caller == address(0)) revert systemError("ZeroAddress");
        _unpause();
    }

    // =============================================================
    // FALLBACK FUNCTIONS
    // =============================================================

    receive() external payable {
        revert systemError("DirectEtherTransferNotAllowed");
    }

    fallback() external payable {
        revert systemError("FunctionNotFound");
    }

    // =============================================================
    // UPGRADE AUTHORIZATION
    // =============================================================

    function _authorizeUpgrade(address newImplementation)
        internal
        view
        override
        onlyOwner
        whenNotPaused
    {
        if (newImplementation == address(0)) revert systemError("ZeroAddress");
    }
}

contracts/mainSystem/module/Cancellation.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../../system/interfaces/taskCTCcall/ITaskData.sol";
import "../../system/interfaces/taskCTCcall/ICancellationLogic.sol";
import "../../system/interfaces/IAddressRegistry.sol";
import "../../system/interfaces/CTCcall/IUsers.sol";
import "../../system/interfaces/IDataContract.sol";

/**
 * @title CancellationLogic
 * @notice Handles task cancellations and deadline triggers
 * @dev Stateless logic contract - all state access via CTC calls to taskData
 */
contract CancellationLogic is ICancellationLogic {
    // =============================================================
    // STATE VARIABLES
    // =============================================================
    IAddressRegistry public addressRegistry;

    modifier ctcCall() {
        if(msg.sender != addressRegistry.__taskComponentsAddr().taskControler) revert CancellationErr("UnauthorizedCaller");
        _;
        
    }

    // =============================================================
    // INITIALIZATION
    // =============================================================
    constructor(address _addressRegistry) {
        if (_addressRegistry == address(0)) {
            revert CancellationErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(_addressRegistry);
    }

    function _getTaskDataContract() internal view returns (ITaskData) {
        return ITaskData(addressRegistry.__taskComponentsAddr().dataContract);
    }

    function _getUsersContract() internal view returns (IUsers) {
        return IUsers(addressRegistry.__usersContract());
    }

    function _getDataContract() internal view returns (IDataContract) {
        return IDataContract(addressRegistry.__dataContract());
    }

    // =============================================================
    // CANCELLATION FUNCTIONS
    // =============================================================

    /**
     * @notice Cancels a task by either creator or member
     * @dev Applies penalties and returns remaining funds
     */
    function __cancelByMe(uint256 taskId, address user) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        if (user != t.creator && user != t.member) {
            revert CancellationErr("NotCounterparty");
        }
        if (t.status != ITaskData.TaskStatus.InProgres) {
            revert CancellationErr("InvalidStatus");
        }

        if (user == t.member) {
            // Member cancels: member pays penalty to creator
            uint256 penaltyToCreator = (t.memberStake * _getDataContract().__getNegPenalty()) / 100;
            uint256 memberReturn = (t.memberStake * (100 - _getDataContract().__getNegPenalty())) / 100;

            _getUsersContract().__addUserBalance(t.creator, t.creatorStake + t.reward + penaltyToCreator);
            _getUsersContract().__addUserBalance(t.member, memberReturn);
        } else {
            // Creator cancels: creator pays penalty to member
            if (t.member == address(0)) {
                revert CancellationErr("NoMemberAssigned");
            }

            uint256 penaltyToMember = (t.creatorStake * _getDataContract().__getNegPenalty()) / 100;
            uint256 creatorReturn = (t.creatorStake * (100 - _getDataContract().__getNegPenalty())) / 100 + t.reward;

            _getUsersContract().__addUserBalance(t.member, t.memberStake + penaltyToMember);
            _getUsersContract().__addUserBalance(t.creator, creatorReturn);
        }

        // Update task state
        _getTaskDataContract().__updateTaskFlags(taskId, false, false, t.isRewardClaimed);
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.Cancelled);

        // Update reputation
        _getUsersContract().__cancelByMeRep(t.member);
        _getUsersContract().__cancelByMeRep(t.creator);
        _getUsersContract().__taskFailCounter(t.member, t.creator);

        emit CancellationEvent(taskId, user, "TaskCancelledByMe");
    }

    /**
     * @notice Triggers deadline consequence if task not completed
     * @dev Penalties applied if deadline exceeded with pending submission
     */
    function __triggerDeadline(uint256 taskId) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        ITaskData.TaskSubmitData memory s = _getTaskDataContract().__getTaskSubmit(taskId);

        if (s.status == ITaskData.SubmitStatus.Pending) {
            revert CancellationErr("SubmissionError");
        }
        if (t.status != ITaskData.TaskStatus.InProgres) {
            revert CancellationErr("InvalidStatus");
        }
        if (t.deadlineAt == 0) {
            revert CancellationErr("InvalidDeadline");
        }
        if (block.timestamp < t.deadlineAt) {
            revert CancellationErr("DeadlineNotExceeded");
        }

        // Distribute penalties
        if (t.member != address(0) && t.memberStake > 0) {
            uint256 toMember = (t.memberStake * _getDataContract().__getNegPenalty()) / 100;
            uint256 toCreator = (t.memberStake * (100 - _getDataContract().__getNegPenalty())) / 100;

            _getUsersContract().__addUserBalance(t.member, toMember);
            _getUsersContract().__addUserBalance(t.creator, toCreator + t.creatorStake + t.reward);
        } else {
            _getUsersContract().__addUserBalance(t.creator, t.creatorStake + t.reward);
        }

        // Update task state
        _getTaskDataContract().__updateTaskFlags(taskId, false, false, t.isRewardClaimed);
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.Cancelled);

        // Apply reputation penalties
        // SECURITY FIX C-3: Remove unnecessary __penaltyIsBiggerThanReputation guards
        // Safe subtraction is now handled in __deadlineHitRep
        if (_getUsersContract().__isRegistered(t.member) && _getUsersContract().__isRegistered(t.creator)) {
            _getUsersContract().__deadlineHitRep(t.member, t.creator);
        }

        _getUsersContract().__taskFailCounter(t.creator, t.member);

        emit CancellationEvent(taskId, address(0), "DeadlineTriggered");
    }

    // =============================================================
    // INTERNAL ADDRESS REGISTRY
    // =============================================================

    /**
     * @notice Change address registry reference and called in controller
     */
    function __changeAddressRegistry(address newAddress) external override ctcCall {
        if (newAddress == address(0)) {
            revert CancellationErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(newAddress);
        emit CancellationEvent(0, newAddress, "addressRegistryUpdated");
    }
}

contracts/mainSystem/module/JoinRequestL.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../../system/interfaces/taskCTCcall/ITaskData.sol";
import "../../system/interfaces/taskCTCcall/IJoinRequestLogic.sol";
import "../../system/interfaces/IAddressRegistry.sol";
import "../../system/interfaces/CTCcall/IUsers.sol";
import "../../system/interfaces/IDataContract.sol";

/**
 * @title JoinRequestLogic
 * @notice Handles task join requests, approvals, and rejections
 * @dev Stateless logic contract - all state access via CTC calls to taskData
 */
contract JoinRequestLogic is IJoinRequestLogic {
    // =============================================================
    // STATE VARIABLES
    // =============================================================
    IAddressRegistry public addressRegistry;

    modifier ctcCall() {
        if (msg.sender != addressRegistry.__taskComponentsAddr().taskControler)
            revert JoinRequestErr("UnauthorizedCaller");
        _;
    }

    // =============================================================
    // INITIALIZATION
    // =============================================================
    constructor(address _addressRegistry) {
        if (_addressRegistry == address(0)) {
            revert JoinRequestErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(_addressRegistry);
    }

    function _getTaskDataContract() internal view returns (ITaskData) {
        return ITaskData(addressRegistry.__taskComponentsAddr().dataContract);
    }

    function _getUsersContract() internal view returns (IUsers) {
        return IUsers(addressRegistry.__usersContract());
    }

    function _getDataContract() internal view returns (IDataContract) {
        return IDataContract(addressRegistry.__dataContract());
    }

    // =============================================================
    // JOIN REQUEST FUNCTIONS
    // =============================================================

    /**
     * @notice Requests to join a task with stake
     * @dev Validates task status and user eligibility
     * @dev SECURITY FIX C-1: ETH is now pre-deposited in UsersContract, don't expect msg.value
     */
    function __requestJoinTask(uint256 taskId, address user) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        if (t.status != ITaskData.TaskStatus.OpenRegistration) {
            revert JoinRequestErr("InvalidStatus");
        }

        if (user == t.creator) {
            revert JoinRequestErr("CannotJoinOwnTask");
        }

        // Calculate required stake
        uint256 requiredStake = (t.reward * _getDataContract().__getMemberStakeFromRewardPercentage()) / 100;

        // Check for existing pending request - O(1) lookup
        if (_getTaskDataContract().__hasPendingRequest(taskId, user)) {
            revert JoinRequestErr("AlreadyRequested");
        }

        // SECURITY FIX C-1: Check user balance (which now includes deposited ETH)
        uint256 userBalance = _getUsersContract().__getUserBalance(user);
        if (userBalance < requiredStake) {
            revert JoinRequestErr("InsufficientStake");
        }

        // Deduct stake from user's balance (ETH is now in UsersContract vault)
        _getUsersContract().__takeUserBalance(user, requiredStake);

        ITaskData.JoinRequestData memory newRequest = ITaskData.JoinRequestData({
            applicant: user,
            stakeAmount: requiredStake,
            status: ITaskData.UserTask.Request,
            isPending: true,
            hasWithdrawn: false
        });

        _getTaskDataContract().__addJoinRequest(taskId, newRequest);

        emit JoinRequestEvent(taskId, user, "JoinRequested");
    }

    /**
     * @notice Withdraws a pending join request
     * @dev Returns stake to user
     */
    function __withdrawJoinRequest(uint256 taskId, address user) external override ctcCall {
        // Get request data using O(1) lookup
        ITaskData.JoinRequestData memory request = _getTaskDataContract().__getJoinRequestByUser(taskId, user);

        if (!request.isPending || request.hasWithdrawn) {
            revert JoinRequestErr("NoPendingRequest");
        }

        uint256 index = _getTaskDataContract().joinRequestIndex(taskId, user);
        uint256 stake = request.stakeAmount;

        _getTaskDataContract().__updateJoinRequestStatus(taskId, index, ITaskData.UserTask.Cancelled);
        _getTaskDataContract().__updateJoinRequestFlags(taskId, index, false, true);

        _getUsersContract().__addUserBalance(user, stake);

        emit JoinRequestEvent(taskId, user, "JoinrequestCancelled");
    }

    /**
     * @notice Approves a join request
     * @dev Only callable by task creator, transitions task to InProgress
     */
    function __approveJoinRequest(uint256 taskId, address applicant) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        // SECURITY FIX H-6: Ensure task is still in OpenRegistration status
        if (t.status != ITaskData.TaskStatus.OpenRegistration) {
            revert JoinRequestErr("InvalidStatus");
        }

        // Get request data using O(1) lookup
        ITaskData.JoinRequestData memory request = _getTaskDataContract().__getJoinRequestByUser(taskId, applicant);

        if (!request.isPending) {
            revert JoinRequestErr("NoPendingRequest");
        }

        uint256 index = _getTaskDataContract().joinRequestIndex(taskId, applicant);
        uint256 stakeAmount = request.stakeAmount;

        // Update join request
        _getTaskDataContract().__updateJoinRequestStatus(taskId, index, ITaskData.UserTask.Accepted);
        _getTaskDataContract().__updateJoinRequestFlags(taskId, index, false, true);

        // Update task with member info
        _getTaskDataContract().__updateTaskParticipants(taskId, t.creator, applicant);
        _getTaskDataContract().__updateTaskFinancials(taskId, t.value, t.reward, t.creatorStake, stakeAmount);
        _getTaskDataContract().__updateTaskFlags(taskId, true, t.isCreatorStakeLocked, t.isRewardClaimed);

        // Set deadline
        uint256 newDeadline = block.timestamp + (uint256(t.deadlineHours) * 1 hours);
        _getTaskDataContract().__updateTaskDeadline(taskId, newDeadline, t.deadlineHours);
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.InProgres);

        emit JoinRequestEvent(taskId, applicant, "JoinApproved");
    }

    function __approveAndRejectOthers(uint256 taskId, address applicant) external ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        // SECURITY FIX NEW-M-1: Add status check to prevent overwriting approved member
        if (t.status != ITaskData.TaskStatus.OpenRegistration) {
            revert JoinRequestErr("InvalidStatus");
        }

        ITaskData.JoinRequestData memory request = _getTaskDataContract().__getJoinRequestByUser(taskId, applicant);

        if (!request.isPending) {
            revert JoinRequestErr("NoPendingRequest");
        }

        uint256 approvedIndex = _getTaskDataContract().joinRequestIndex(taskId, applicant);

        _getTaskDataContract().__updateJoinRequestStatus(taskId, approvedIndex, ITaskData.UserTask.Accepted);

        _getTaskDataContract().__updateJoinRequestFlags(taskId, approvedIndex, false, true);

        ITaskData.JoinRequestData[] memory requests = _getTaskDataContract().__getJoinRequests(taskId);

        for (uint256 i; i < requests.length; ++i) {
            address currentApplicant = requests[i].applicant;

            if (currentApplicant != applicant && requests[i].isPending) {
                uint256 idx = _getTaskDataContract().joinRequestIndex(taskId, currentApplicant);

                _getTaskDataContract().__updateJoinRequestStatus(taskId, idx, ITaskData.UserTask.Rejected);

                _getTaskDataContract().__updateJoinRequestFlags(taskId, idx, false, true);

                _getUsersContract().__addUserBalance(currentApplicant, requests[i].stakeAmount);
            }
        }

        _getTaskDataContract().__updateTaskParticipants(taskId, t.creator, applicant);

        _getTaskDataContract().__updateTaskFinancials(taskId, t.value, t.reward, t.creatorStake, request.stakeAmount);

        _getTaskDataContract().__updateTaskFlags(taskId, true, t.isCreatorStakeLocked, t.isRewardClaimed);

        uint256 newDeadline = block.timestamp + (uint256(t.deadlineHours) * 1 hours);

        _getTaskDataContract().__updateTaskDeadline(taskId, newDeadline, t.deadlineHours);

        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.InProgres);

        emit JoinRequestEvent(taskId, applicant, "JoinApprovedAndOthersRejected");
    }

    /**
     * @notice Rejects a join request
     * @dev Only callable by task creator, returns stake to applicant
     */
    function __rejectJoinRequest(uint256 taskId, address _applicant) external override ctcCall {
        // Get request data using O(1) lookup
        ITaskData.JoinRequestData memory request = _getTaskDataContract().__getJoinRequestByUser(taskId, _applicant);

        if (!request.isPending) {
            revert JoinRequestErr("NoPendingRequest");
        }

        uint256 index = _getTaskDataContract().joinRequestIndex(taskId, _applicant);
        uint256 stake = request.stakeAmount;

        _getTaskDataContract().__updateJoinRequestStatus(taskId, index, ITaskData.UserTask.Rejected);
        _getTaskDataContract().__updateJoinRequestFlags(taskId, index, false, true);

        _getUsersContract().__addUserBalance(_applicant, stake);

        emit JoinRequestEvent(taskId, _applicant, "JoinRejected");
    }

    // =============================================================
    // INTERNAL ADDRESS REGISTRY
    // =============================================================

    /**
     * @notice Change address registry reference and called in controller
     */
    function __changeAddressRegistry(address newAddress) external override ctcCall {
        if (newAddress == address(0)) {
            revert JoinRequestErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(newAddress);
        emit JoinRequestEvent(0, newAddress, "addressRegistryUpdated");
    }
}

contracts/mainSystem/module/SubmissionLo.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../../system/interfaces/taskCTCcall/ITaskData.sol";
import "../../system/interfaces/taskCTCcall/ISubmissionLogic.sol";
import "../../system/interfaces/taskCTCcall/ICancellationLogic.sol";
import "../../system/interfaces/IAddressRegistry.sol";
import "../../system/interfaces/CTCcall/IUsers.sol";
import "../../system/interfaces/IDataContract.sol";

/**
 * @title SubmissionLogic
 * @notice Handles task submissions, revisions, and approvals
 * @dev Stateless logic contract - all state access via CTC calls to taskData
 */
contract SubmissionLogic is ISubmissionLogic {
    // =============================================================
    // STATE VARIABLES
    // =============================================================
    IAddressRegistry public addressRegistry;

    modifier ctcCall() {
        if(msg.sender != addressRegistry.__taskComponentsAddr().taskControler) revert SubmissionErr("UnauthorizedCaller");
        _;
    }

    // =============================================================
    // INITIALIZATION
    // =============================================================
    constructor(address _addressRegistry) {
        if (_addressRegistry == address(0)) {
            revert SubmissionErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(_addressRegistry);
    }

    function _getTaskDataContract() internal view returns (ITaskData) {
        return ITaskData(addressRegistry.__taskComponentsAddr().dataContract);
    }

    function _getUsersContract() internal view returns (IUsers) {
        return IUsers(addressRegistry.__usersContract());
    }

    function _getDataContract() internal view returns (IDataContract) {
        return IDataContract(addressRegistry.__dataContract());
    }

    function _getTaskCancellationContract() internal view returns (ICancellationLogic) {
        return ICancellationLogic(addressRegistry.__taskComponentsAddr().cancelModule);
    }

    // =============================================================
    // SUBMISSION FUNCTIONS
    // =============================================================

    /**
     * @notice Submits a task for review
     * @dev Only callable by task member, task must be in progress
     */
    function __requestSubmitTask(
        uint256 taskId,
        string calldata PullRequestURL,
        string calldata Note,
        address user
    ) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        if (t.status != ITaskData.TaskStatus.InProgres) {
            revert SubmissionErr("InvalidStatus");
        }

        // SECURITY FIX M-1, NEW-H-2: Add deadline check - late submissions should be blocked
        // Cannot call __triggerDeadline here due to ctcCall routing issue
        // (msg.sender would be submisionModule not taskControler, causing revert)
        if (block.timestamp > t.deadlineAt && t.deadlineAt != 0) {
            revert SubmissionErr("SubmissionPastDeadline");
        }

        ITaskData.TaskSubmitData memory existingSubmit = _getTaskDataContract().__getTaskSubmit(taskId);
        if (existingSubmit.sender != address(0) && existingSubmit.status == ITaskData.SubmitStatus.Pending) {
            revert SubmissionErr("SubmissionError");
        }

        ITaskData.TaskSubmitData memory newSubmit = ITaskData.TaskSubmitData({
            githubURL: PullRequestURL,
            note: Note,
            sender: user,
            status: ITaskData.SubmitStatus.Pending,
            revisionTime: 0,
            newDeadline: t.deadlineAt
        });

        _getTaskDataContract().__setTaskSubmit(taskId, newSubmit);

        emit SubmissionEvent(taskId, user, "TaskSubmitted");
    }

    /**
     * @notice Resubmits a task after revision request
     * @dev Only callable by task member after revision is requested
     */
    function __reSubmitTask(
        uint256 taskId,
        string calldata Note,
        string calldata GithubFixedURL,
        address user
    ) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        ITaskData.TaskSubmitData memory s = _getTaskDataContract().__getTaskSubmit(taskId);

        if (s.status != ITaskData.SubmitStatus.RevisionNeeded) {
            revert SubmissionErr("InvalidStatus");
        }

        // SECURITY FIX H-3: Check revision count before updating to prevent stale memory reads
        if (s.revisionTime >= t.maxRevision) {
            // Max revisions exceeded - auto-approve the task
            __approveTask(taskId);
            return;
        }

        // Update submission and refresh from storage
        _getTaskDataContract().__updateSubmitContent(taskId, GithubFixedURL, Note);
        _getTaskDataContract().__updateSubmitStatus(taskId, ITaskData.SubmitStatus.Pending);

        emit SubmissionEvent(taskId, user, "TaskReSubmitted");
    }

    /**
     * @notice Requests revision on a submission
     * @dev Only callable by task creator
     */
    function __requestRevision(
        uint256 taskId,
        string calldata Note,
        uint256 additionalDeadlineHours
    ) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        ITaskData.TaskSubmitData memory s = _getTaskDataContract().__getTaskSubmit(taskId);

        if (s.status != ITaskData.SubmitStatus.Pending) {
            revert SubmissionErr("InvalidStatus");
        }

        uint256 additionalSeconds = (additionalDeadlineHours * 1 hours);
        uint256 newDeadline = block.timestamp + additionalSeconds;
        uint256 newRevisionTime = s.revisionTime + 1;

        // SECURITY FIX H-3: Check max revisions BEFORE updating submission state
        if (newRevisionTime > t.maxRevision) {
            // Max revisions exceeded - auto-approve the task instead of requesting revision
            __approveTask(taskId);
            return;
        }

        // Update submission
        _getTaskDataContract().__updateSubmitStatus(taskId, ITaskData.SubmitStatus.RevisionNeeded);
        _getTaskDataContract().__updateSubmitContent(taskId, s.githubURL, Note);
        _getTaskDataContract().__updateSubmitRevision(taskId, newRevisionTime, newDeadline);
        _getTaskDataContract().__updateTaskDeadline(taskId, newDeadline, t.deadlineHours);

        // Apply reputation penalties
        // SECURITY FIX C-3: Remove dangerous __penaltyIsBiggerThanReputation guards
        // Safe subtraction is now handled in __revisionRep
        if (_getUsersContract().__isRegistered(t.member) && _getUsersContract().__isRegistered(t.creator)) {
            _getUsersContract().__revisionRep(t.member, t.creator);
        }

        emit SubmissionEvent(taskId, address(0), "RevisionRequested");
    }

    /**
     * @notice Approves a task submission
     * @dev Only callable by task creator, distributes rewards
     * @dev SECURITY FIX M-5: Implement fee collection mechanism
     */
    function __approveTask(uint256 taskId) public override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        ITaskData.TaskSubmitData memory s = _getTaskDataContract().__getTaskSubmit(taskId);

        if (t.status != ITaskData.TaskStatus.InProgres) {
            revert SubmissionErr("InvalidStatus");
        }
        if (s.status != ITaskData.SubmitStatus.Pending) {
            revert SubmissionErr("SubmissionError");
        }
        if (t.isRewardClaimed) {
            revert SubmissionErr("AlreadyClaimed");
        }

        // SECURITY FIX M-5: Implement fee collection
        uint256 feePercentage = _getDataContract().__getFeePercentage();
        uint256 feeAmount = (t.reward * feePercentage) / 100;
        uint256 memberReward = t.reward - feeAmount;
        
        uint256 memberGet = memberReward + t.memberStake;
        uint256 creatorGet = t.creatorStake;

        // Update task flags and status
        _getTaskDataContract().__updateTaskFlags(taskId, false, false, true);
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.Completed);

        // Clear submission data
        ITaskData.TaskSubmitData memory emptySubmit = ITaskData.TaskSubmitData({
            githubURL: "",
            note: "",
            sender: address(0),
            status: ITaskData.SubmitStatus.NoneStatus,
            revisionTime: 0,
            newDeadline: 0
        });
        _getTaskDataContract().__setTaskSubmit(taskId, emptySubmit);

        // Distribute rewards (minus fees)
        _getUsersContract().__addUserBalance(t.member, memberGet);
        _getUsersContract().__addUserBalance(t.creator, creatorGet);
        
        // Collect fees for protocol
        if (feeAmount > 0) {
            _getTaskDataContract().__increaseFee(feeAmount);
        }

        // Update reputation
        if (_getUsersContract().__isRegistered(t.member) && _getUsersContract().__isRegistered(t.creator)) {
            _getUsersContract().__taskAcceptRep(t.member, t.creator);
        }

        _getUsersContract().__taskCompleteCounter(t.member, t.creator);

        emit SubmissionEvent(taskId, address(0), "TaskApproved");
    }

    // =============================================================
    // INTERNAL ADDRESS REGISTRY
    // =============================================================

    /**
     * @notice Change address registry reference and called in controller
     */
    function __changeAddressRegistry(address newAddress) external override ctcCall {
        if (newAddress == address(0)) {
            revert SubmissionErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(newAddress);
        emit SubmissionEvent(0, newAddress, "addressRegistryUpdated");
    }
}

contracts/mainSystem/module/TaskLifecycl.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../../system/interfaces/taskCTCcall/ITaskData.sol";
import "../../system/interfaces/taskCTCcall/ITaskLifecycleLogic.sol";
import "../../system/interfaces/IAddressRegistry.sol";
import "../../system/interfaces/CTCcall/IUsers.sol";
import "../../system/interfaces/IDataContract.sol";

/**
 * @title TaskLifecycleLogic
 * @notice Handles task creation, deletion, activation, and registration management
 * @dev Stateless logic contract - all state access via CTC calls to taskData
 */
contract TaskLifecycleLogic is ITaskLifecycleLogic {
    // =============================================================
    // STATE VARIABLES
    // =============================================================
    IAddressRegistry public addressRegistry;

    modifier ctcCall() {
        if (msg.sender != addressRegistry.__taskComponentsAddr().taskControler)
            revert TaskLifecycleErr("UnauthorizedCaller");
        _;
    }

    // =============================================================
    // INITIALIZATION
    // =============================================================
    constructor(address _addressRegistry) {
        if (_addressRegistry == address(0)) {
            revert TaskLifecycleErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(_addressRegistry);
    }

    function _getTaskDataContract() internal view returns (ITaskData) {
        return ITaskData(addressRegistry.__taskComponentsAddr().dataContract);
    }

    function _getUsersContract() internal view returns (IUsers) {
        return IUsers(addressRegistry.__usersContract());
    }

    function _getDataContract() internal view returns (IDataContract) {
        return IDataContract(addressRegistry.__dataContract());
    }

    // =============================================================
    // TASK LIFECYCLE FUNCTIONS
    // =============================================================

    /**
     * @notice Creates a new task
     * @dev Only callable from TaskController via CTC
     * @dev SECURITY FIX C-1: Deduct reward from user balance, not from msg.value
     * @dev SECURITY FIX NEW-M-2: Validate reward amount to prevent spam
     */
    function __createTask(
        string memory _Title,
        string memory _GithubURL,
        uint128 _DeadlineHours,
        uint128 _MaximumRevision,
        uint256 _rewardAmount,
        address _user
    ) external override ctcCall returns (uint256 taskId) {
        // SECURITY FIX NEW-M-2: Enforce minimum reward value
        if (_rewardAmount == 0) {
            revert TaskLifecycleErr("ZeroReward");
        }

        (uint256 _taskCounter, ) = _getTaskDataContract().__getGlobalState();
        taskId = _taskCounter;

        // SECURITY FIX C-1: Check user has enough balance for reward
        uint256 userBalance = _getUsersContract().__getUserBalance(_user);
        if (userBalance < _rewardAmount) {
            revert TaskLifecycleErr("InsufficientReward");
        }

        // SECURITY FIX C-1: Deduct reward from user's balance (stored in UsersContract vault)
        _getUsersContract().__takeUserBalance(_user, _rewardAmount);

        uint256 projectValue = ___getProjectValue(_DeadlineHours, _MaximumRevision, _rewardAmount, _user);

        ITaskData.TaskData memory newTask = ITaskData.TaskData({
            status: ITaskData.TaskStatus.Created,
            taskId: taskId,
            value: projectValue,
            reward: _rewardAmount,
            deadlineAt: 0,
            createdAt: block.timestamp,
            creatorStake: 0,
            memberStake: 0,
            maxRevision: _MaximumRevision,
            deadlineHours: _DeadlineHours,
            creator: _user,
            member: address(0),
            title: _Title,
            githubURL: _GithubURL,
            isMemberStakeLocked: false,
            isCreatorStakeLocked: false,
            isRewardClaimed: false,
            exists: true
        });

        _getTaskDataContract().__createTask(newTask);
        _getUsersContract().__taskCreateCounter(_user);

        emit TaskLifecycleEvent(taskId, _user, "TaskCreated");

        return taskId;
    }

    /**
     * @notice Deletes a task
     * @dev Only callable by task creator
     * @dev SECURITY FIX H-1, H-2: Cannot delete tasks with assigned members due to ctcCall routing
     * @dev Cross-module calls violate ctcCall invariant - member cancellations must route through TaskController
     */
    function __deleteTask(uint256 _taskId, address _user) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(_taskId);

        if (t.member != address(0)) {
            // SECURITY FIX H-1: Cannot directly call CancellationLogic here
            // The ctcCall modifier in CancellationLogic checks msg.sender == taskControler
            // but msg.sender here is taskLifecycleModule, causing the call to revert
            // Solution: Require deletion via TaskController.cancelByMe() instead
            revert TaskLifecycleErr("CannotDeleteTaskWithMember");
        } else {
            // SECURITY FIX H-2: Refund all pending join request stakes before deletion
            ITaskData.JoinRequestData[] memory requests = _getTaskDataContract().__getJoinRequests(_taskId);
            for (uint256 i = 0; i < requests.length; i++) {
                if (requests[i].isPending && !requests[i].hasWithdrawn) {
                    _getUsersContract().__addUserBalance(requests[i].applicant, requests[i].stakeAmount);
                }
            }
            
            // Return creator's funds if no member assigned
            _getUsersContract().__addUserBalance(_user, t.reward);
            if (t.creatorStake > 0) {
                _getUsersContract().__addUserBalance(_user, t.creatorStake);
            }
            
            // Update task status to Cancelled
            _getTaskDataContract().__updateTaskStatus(_taskId, ITaskData.TaskStatus.Cancelled);
            _getTaskDataContract().__updateTaskFlags(_taskId, false, false, t.isRewardClaimed);
        }

        emit TaskLifecycleEvent(_taskId, _user, "TaskDeleted");
    }

    /**
     * @notice Activates a task by requiring creator stake
     * @dev Creator must provide stake amount based on task parameters
     * @dev SECURITY FIX H-5: Ensure task is in Created status before activation
     * @dev SECURITY FIX C-1: ETH is now pre-deposited in UsersContract, don't expect msg.value
     */
    function __activateTask(uint256 taskId, address user) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);

        // SECURITY FIX H-5: Check that task is in Created status to prevent repeated activation
        if (t.status != ITaskData.TaskStatus.Created) {
            revert TaskLifecycleErr("InvalidStatus");
        }

        uint256 requiredStake = ___getCreatorStake(t.deadlineHours, t.maxRevision, t.reward, user);

        uint256 userBalance = _getUsersContract().__getUserBalance(user);
        
        // SECURITY FIX C-1: No msg.value to add - all ETH is already in UsersContract balance
        if (userBalance < requiredStake) {
            revert TaskLifecycleErr("InsufficientStake");
        }

        // Deduct required stake from user's balance
        _getUsersContract().__takeUserBalance(user, requiredStake);

        _getTaskDataContract().__updateTaskFinancials(taskId, t.value, t.reward, requiredStake, t.memberStake);
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.Active);
        _getTaskDataContract().__updateTaskFlags(taskId, t.isMemberStakeLocked, true, t.isRewardClaimed);

        emit TaskLifecycleEvent(taskId, user, "TaskActive");
    }

    /**
     * @notice Opens registration for task
     * @dev Only callable by task creator
     */
    function __openRegistration(uint256 taskId) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        if (t.status != ITaskData.TaskStatus.Active) {
            revert TaskLifecycleErr("TaskNotOpen");
        }
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.OpenRegistration);
        emit TaskLifecycleEvent(taskId, t.creator, "RegistrationOpened");
    }

    /**
     * @notice Closes registration for task
     * @dev Only callable by task creator
     */
    function __closeRegistration(uint256 taskId) external override ctcCall {
        ITaskData.TaskData memory t = _getTaskDataContract().__getTask(taskId);
        if (t.status != ITaskData.TaskStatus.OpenRegistration) {
            revert TaskLifecycleErr("TaskNotOpen");
        }
        _getTaskDataContract().__updateTaskStatus(taskId, ITaskData.TaskStatus.Active);
        emit TaskLifecycleEvent(taskId, t.creator, "RegistrationClosed");
    }

    // =============================================================
    // INTERNAL VIEW FUNCTIONS
    // =============================================================

    /**
     * @notice Calculates required creator stake
     */
    function ___getCreatorStake(
        uint128 DeadlineHours,
        uint128 MaximumRevision,
        uint256 rewardWei,
        address Caller
    ) public view override returns (uint256) {
        uint256 category = ___getProjectValue(DeadlineHours, MaximumRevision, rewardWei, Caller);
        return (category * _getDataContract().__getCreatorStakeFromProjectValuePercentage()) / 100;
    }

    /**
     * @notice Calculates project value based on task parameters and user reputation
     */
    function ___getProjectValue(
        uint128 DeadlineHours,
        uint128 MaximumRevision,
        uint256 rewardWei,
        address Caller
    ) public view override returns (uint256) {
        uint256 rewardEtherUnits = rewardWei / 1 ether;

        IUsers users = IUsers(addressRegistry.__usersContract());

        uint256 pos = (_getDataContract().__getRewardScore() * rewardEtherUnits) +
            (_getDataContract().__getRevisionScore() * MaximumRevision);

        uint256 neg = (_getDataContract().__getReputationScore() * users.__getUserReputation(Caller)) +
            (_getDataContract().__getDeadlineScore() * DeadlineHours);

        // Use ratio-based calculation: higher neg scales down value gracefully instead of zeroing it
        uint256 rawValue = (pos > neg) ? (pos - neg) : (pos * 100) / (neg / (1 ether) + 1);

        return (rawValue * 1 ether) / 100;
    }

    // =============================================================
    // INTERNAL ADDRESS REGISTRY
    // =============================================================

    /**
     * @notice Change address registry reference and called in controller
     */
    function __changeAddressRegistry(address newAddress) external override ctcCall {
        if (newAddress == address(0)) {
            revert TaskLifecycleErr("ZeroAddress");
        }
        addressRegistry = IAddressRegistry(newAddress);
        emit TaskLifecycleEvent(0, newAddress, "addressRegistryUpdated");
    }
}

interface ICancellationLogic {
    function __cancelByMe(uint256 taskId, address user) external;
}

contracts/mainSystem/taskData.sol.content:
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity ^0.8.20;

import "../system/interfaces/IAddressRegistry.sol";
import "../system/utils/addressUtils.sol";
import "../Pipe/AccesControlPipes.sol";

import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract taskData is 
    AddressUtils, 
    Initializable, 
    UUPSUpgradeable, 
    PausableUpgradeable,
    MainAccesControlPipes {

    // =============================================================
    // ENUMS
    // =============================================================
    enum TaskStatus { 
        NonExistent, 
        Created, 
        Active, 
        OpenRegistration, 
        InProgres, 
        Completed, 
        Cancelled 
    }

    enum UserTask { 
        None, 
        Request, 
        Accepted, 
        Rejected, 
        Cancelled 
    }

    enum SubmitStatus { 
        NoneStatus, 
        Pending, 
        RevisionNeeded, 
        Accepted 
    }

    // =============================================================
    // STRUCTS
    // =============================================================
    struct TaskData {
        TaskStatus status;
        uint256 taskId;
        uint256 value;
        uint256 reward;
        uint256 deadlineAt;
        uint256 createdAt;
        uint256 creatorStake;
        uint256 memberStake;
        uint128 maxRevision;
        uint128 deadlineHours;
        address creator;
        address member;
        string title;
        string githubURL;
        bool isMemberStakeLocked;
        bool isCreatorStakeLocked;
        bool isRewardClaimed;
        bool exists;
    }

    struct JoinRequestData {
        address applicant;
        uint256 stakeAmount;
        UserTask status;
        bool isPending;
        bool hasWithdrawn;
    }

    struct TaskSubmitData {
        string githubURL;
        string note;
        address sender;
        SubmitStatus status;
        uint256 revisionTime;
        uint256 newDeadline;
    }

    // =============================================================
    // STORAGE
    // =============================================================
    mapping(uint256 => TaskSubmitData) public TaskSubmits;
    mapping(uint256 => TaskData) public Tasks;
    mapping(uint256 => JoinRequestData[]) public joinRequests;

    // Optimized mappings for O(1) join request lookups
    // hasPendingRequest[taskId][user] = true if user has a pending join request for taskId
    mapping(uint256 => mapping(address => bool)) public hasPendingRequest;
    // joinRequestIndex[taskId][user] = index in joinRequests[taskId] array for user's request
    mapping(uint256 => mapping(address => uint256)) public joinRequestIndex;

    uint256 public taskCounter;
    uint256 public feeCollected;

    IAddressRegistry public addressRegistry;

    uint256[50] private ___gap;

    // =============================================================
    // event & error
    // =============================================================
    event taskDataEvent(string eventName, uint256 indexed taskId, address indexed caller, bytes extraData);
    error taskDataErr(string message);

    // =============================================================
    // MODIFIER
    // =============================================================
    modifier ctcCall() {
        require(
            msg.sender == addressRegistry.__taskComponentsAddr().cancelModule ||
            msg.sender == addressRegistry.__taskComponentsAddr().joinModule ||
            msg.sender == addressRegistry.__taskComponentsAddr().submisionModule ||
            msg.sender == addressRegistry.__taskComponentsAddr().taskLifecycleModule ||
            msg.sender == addressRegistry.__taskComponentsAddr().taskControler,
            "Unauthorized caller"
        );
        _;
    }

    modifier onlyOwner {
        __onlyOwner(addressRegistry.__accessControlContract());
        _;
    }

    // =============================================================
    // INITIAL SETUP
    // =============================================================
    function initialize(
        address _registryAddress
    ) public initializer {
        // Validate input addresses
        if (_registryAddress == address(0)) revert taskDataErr("ZeroAddress");

        // Initialize parent contracts
        __Pausable_init();

        // Set up access control and state variables
        addressRegistry = IAddressRegistry(_registryAddress);

        taskCounter = 0;
        feeCollected = 0;
    }

    // =============================================================
    // TASK MODIFY FUNCTIONS
    // =============================================================

    function __createTask(TaskData calldata data) external ctcCall {
        require(!Tasks[data.taskId].exists, "Task exists");

        Tasks[data.taskId] = data;
        Tasks[data.taskId].exists = true;

        taskCounter++;
        
        emit taskDataEvent("createTask", data.taskId, msg.sender, abi.encode(data.status, data.value, data.reward, data.creatorStake, data.memberStake, data.deadlineAt, data.creator, data.member));
    }

    function __updateTaskStatus(uint256 taskId, TaskStatus status) external ctcCall {
        require(Tasks[taskId].exists, "Task not found");
        Tasks[taskId].status = status;
        
        emit taskDataEvent("updateTaskStatus", taskId, msg.sender, abi.encode(status));
    }

    function __updateTaskFinancials(
        uint256 taskId,
        uint256 value,
        uint256 reward,
        uint256 creatorStake,
        uint256 memberStake
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.value = value;
        t.reward = reward;
        t.creatorStake = creatorStake;
        t.memberStake = memberStake;
        
        emit taskDataEvent("updateTaskFinancials", taskId, msg.sender, abi.encode(value, reward, creatorStake, memberStake));
    }

    function __updateTaskParticipants(
        uint256 taskId,
        address creator,
        address member
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.creator = creator;
        t.member = member;
        
        emit taskDataEvent("updateTaskParticipants", taskId, msg.sender, abi.encode(creator, member));
    }

    function __updateTaskMetadata(
        uint256 taskId,
        string calldata title,
        string calldata githubURL
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.title = title;
        t.githubURL = githubURL;
        
        emit taskDataEvent("updateTaskMetadata", taskId, msg.sender, abi.encode(title, githubURL));
    }

    function __updateTaskFlags(
        uint256 taskId,
        bool memberStakeLocked,
        bool creatorStakeLocked,
        bool rewardClaimed
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.isMemberStakeLocked = memberStakeLocked;
        t.isCreatorStakeLocked = creatorStakeLocked;
        t.isRewardClaimed = rewardClaimed;
        
        emit taskDataEvent("updateTaskFlags", taskId, msg.sender, abi.encode(memberStakeLocked, creatorStakeLocked, rewardClaimed));
    }

    function __updateTaskDeadline(
        uint256 taskId,
        uint256 deadlineAt,
        uint128 deadlineHours
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.deadlineAt = deadlineAt;
        t.deadlineHours = deadlineHours;
        
        emit taskDataEvent("updateTaskDeadline", taskId, msg.sender, abi.encode(deadlineAt, deadlineHours));
    }

    function __updateTaskRevision(
        uint256 taskId,
        uint128 maxRevision
    ) external ctcCall {
        TaskData storage t = Tasks[taskId];
        require(t.exists, "Task not found");

        t.maxRevision = maxRevision;
        
        emit taskDataEvent("updateTaskRevision", taskId, msg.sender, abi.encode(maxRevision));
    }

    // =============================================================
    // JOIN REQUEST FUNCTIONS
    // =============================================================

    function __addJoinRequest(
        uint256 taskId,
        JoinRequestData calldata request
    ) external ctcCall {
        require(Tasks[taskId].exists, "Task not found");
        require(!hasPendingRequest[taskId][request.applicant], "User already has pending request");

        uint256 newIndex = joinRequests[taskId].length;
        joinRequests[taskId].push(request);
        
        // Update mappings for O(1) lookups
        hasPendingRequest[taskId][request.applicant] = request.isPending;
        if (request.isPending) {
            joinRequestIndex[taskId][request.applicant] = newIndex;
        }
        
        emit taskDataEvent("addJoinRequest", taskId, msg.sender, abi.encode(request.applicant, request.stakeAmount, request.status, request.isPending, request.hasWithdrawn));
    }

    function __updateJoinRequestStatus(
        uint256 taskId,
        uint256 index,
        UserTask status
    ) external ctcCall {
        joinRequests[taskId][index].status = status;
        
        emit taskDataEvent("updateJoinRequestStatus", taskId, msg.sender, abi.encode(index, status));
    }

    function __updateJoinRequestFlags(
        uint256 taskId,
        uint256 index,
        bool isPending,
        bool hasWithdrawn
    ) external ctcCall {
        JoinRequestData storage r = joinRequests[taskId][index];
        bool wasPending = r.isPending;
        r.isPending = isPending;
        r.hasWithdrawn = hasWithdrawn;
        
        // Update mapping if pending status changed
        if (wasPending != isPending) {
            hasPendingRequest[taskId][r.applicant] = isPending;
            if (!isPending) {
                // Clear index when no longer pending
                delete joinRequestIndex[taskId][r.applicant];
            }
        }
        
        emit taskDataEvent("updateJoinRequestFlags", taskId, msg.sender, abi.encode(index, isPending, hasWithdrawn));
    }

    // =============================================================
    // SUBMISSION FUNCTIONS
    // =============================================================

    function __setTaskSubmit(
        uint256 taskId,
        TaskSubmitData calldata data
    ) external ctcCall {
        require(Tasks[taskId].exists, "Task not found");
        TaskSubmits[taskId] = data;
        
        emit taskDataEvent("setTaskSubmit", taskId, msg.sender, abi.encode(data.githubURL, data.note, data.sender, data.status, data.revisionTime, data.newDeadline));
    }

    function __updateSubmitStatus(
        uint256 taskId,
        SubmitStatus status
    ) external ctcCall {
        TaskSubmits[taskId].status = status;
        
        emit taskDataEvent("updateSubmitStatus", taskId, msg.sender, abi.encode(status));
    }

    function __updateSubmitContent(
        uint256 taskId,
        string calldata githubURL,
        string calldata note
    ) external ctcCall {
        TaskSubmitData storage s = TaskSubmits[taskId];
        s.githubURL = githubURL;
        s.note = note;
        
        emit taskDataEvent("updateSubmitContent", taskId, msg.sender, abi.encode(githubURL, note));
    }

    function __updateSubmitRevision(
        uint256 taskId,
        uint256 revisionTime,
        uint256 newDeadline
    ) external ctcCall {
        TaskSubmitData storage s = TaskSubmits[taskId];
        s.revisionTime = revisionTime;
        s.newDeadline = newDeadline;
        
        emit taskDataEvent("updateSubmitRevision", taskId, msg.sender, abi.encode(revisionTime, newDeadline));
    }

    // =============================================================
    // VIEW FUNCTIONS
    // =============================================================

    function __getTask(uint256 taskId) external view returns (TaskData memory) {
        require(Tasks[taskId].exists, "Task not found");
        return Tasks[taskId];
    }

    function __getTaskStatus(uint256 taskId) external view returns (TaskStatus) {
        require(Tasks[taskId].exists, "Task not found");
        return Tasks[taskId].status;
    }

    function __getTaskParticipants(uint256 taskId)
        external
        view
        returns (address creator, address member)
    {
        require(Tasks[taskId].exists, "Task not found");
        TaskData storage t = Tasks[taskId];
        return (t.creator, t.member);
    }

    function __getTaskFinancials(uint256 taskId)
        external
        view
        returns (
            uint256 value,
            uint256 reward,
            uint256 creatorStake,
            uint256 memberStake
        )
    {
        require(Tasks[taskId].exists, "Task not found");
        TaskData storage t = Tasks[taskId];
        return (t.value, t.reward, t.creatorStake, t.memberStake);
    }

    function __getTaskMetadata(uint256 taskId)
        external
        view
        returns (string memory title, string memory githubURL)
    {
        require(Tasks[taskId].exists, "Task not found");
        TaskData storage t = Tasks[taskId];
        return (t.title, t.githubURL);
    }

    function __getTaskFlags(uint256 taskId)
        external
        view
        returns (
            bool isMemberStakeLocked,
            bool isCreatorStakeLocked,
            bool isRewardClaimed
        )
    {
        require(Tasks[taskId].exists, "Task not found");
        TaskData storage t = Tasks[taskId];
        return (
            t.isMemberStakeLocked,
            t.isCreatorStakeLocked,
            t.isRewardClaimed
        );
    }

    function __getJoinRequests(uint256 taskId)
        external
        view
        returns (JoinRequestData[] memory)
    {
        return joinRequests[taskId];
    }

    function __getJoinRequestByIndex(uint256 taskId, uint256 index)
        external
        view
        returns (JoinRequestData memory)
    {
        return joinRequests[taskId][index];
    }

    function __getJoinRequestCount(uint256 taskId)
        external
        view
        returns (uint256)
    {
        return joinRequests[taskId].length;
    }

    /**
     * @notice Check if a user has a pending join request for a task
     * @dev O(1) lookup using mapping instead of O(n) array scan
     * @param taskId The task ID
     * @param user The user address
     * @return True if user has a pending join request
     */
    function __hasPendingRequest(uint256 taskId, address user)
        external
        view
        returns (bool)
    {
        return hasPendingRequest[taskId][user];
    }

    /**
     * @notice Get a user's join request for a task by user address
     * @dev O(1) lookup using mapping instead of O(n) array scan
     * @param taskId The task ID
     * @param user The user address
     * @return The join request data
     */
    function __getJoinRequestByUser(uint256 taskId, address user)
        external
        view
        returns (JoinRequestData memory)
    {
        require(hasPendingRequest[taskId][user], "No pending request for user");
        uint256 index = joinRequestIndex[taskId][user];
        return joinRequests[taskId][index];
    }

    function __getTaskSubmit(uint256 taskId)
        external
        view
        returns (TaskSubmitData memory)
    {
        return TaskSubmits[taskId];
    }

    function __getSubmitStatus(uint256 taskId)
        external
        view
        returns (SubmitStatus)
    {
        return TaskSubmits[taskId].status;
    }

    function __getSubmitContent(uint256 taskId)
        external
        view
        returns (string memory githubURL, string memory note)
    {
        TaskSubmitData storage s = TaskSubmits[taskId];
        return (s.githubURL, s.note);
    }

    function __getSubmitRevision(uint256 taskId)
        external
        view
        returns (uint256 revisionTime, uint256 newDeadline)
    {
        TaskSubmitData storage s = TaskSubmits[taskId];
        return (s.revisionTime, s.newDeadline);
    }

    function __getGlobalState()
        external
        view
        returns (uint256 _taskCounter, uint256 _feeCollected)
    {
        return (taskCounter, feeCollected);
    }

    // =============================================================
    // GLOBAL MODIFY
    // =============================================================

    function __increaseFee(uint256 amount) external ctcCall {
        feeCollected += amount;
        
        emit taskDataEvent("increaseFee", 0, msg.sender, abi.encode(amount, feeCollected));
    }

    function __decreaseFee(uint256 amount) external ctcCall {
        require(feeCollected >= amount, "Insufficient fee");
        feeCollected -= amount;
        
        emit taskDataEvent("decreaseFee", 0, msg.sender, abi.encode(amount, feeCollected));
    }

    // =============================================================
    // OWNER FUNCTIONS
    // =============================================================

    /**
     * @notice Pauses contract
     */
    function pause(address caller) external onlyOwner {
        if (caller == address(0)) revert taskDataErr("ZeroAddress");
        _pause();
        emit taskDataEvent("contract paused", 0, caller, abi.encode(""));
    }

    /**
     * @notice Unpauses contract
     */
    function unpause(address caller) external onlyOwner {
        if (caller == address(0)) revert taskDataErr("ZeroAddress");
        _unpause();
        emit taskDataEvent("contract Unpaused", 0, caller, abi.encode(""));
    }

    /**
     * @notice Change address registry address
     */
    function changeRegistryAddress(address newRegistry) external onlyOwner {
        if (newRegistry == address(0)) revert taskDataErr("ZeroAddress");
        addressRegistry = IAddressRegistry(newRegistry);
        emit taskDataEvent("registry address changed", 0, msg.sender, abi.encode(newRegistry));
    }

    // =============================================================
    // FALLBACK FUNCTIONS
    // =============================================================

    receive() external payable {
        revert taskDataErr("DirectEtherTransferNotAllowed");
    }

    fallback() external payable {
        revert taskDataErr("FunctionNotFound");
    }

    // =============================================================
    // UPGRADE AUTHORIZATION
    // =============================================================

    function _authorizeUpgrade(address newImplementation) internal view override onlyOwner whenNotPaused {
        if (newImplementation == address(0)) revert taskDataErr("ZeroAddress");
    }
}

